-- loses data: t.a changes from integer[] to integer, which keeps only each array's first element
-- loses data: t.b changes from text[] to integer, which keeps only each array's first element
alter table t alter column a type integer using case array_ndims(a) when 1 then a[array_lower(a, 1)] when 2 then a[array_lower(a, 1)][array_lower(a, 2)] when 3 then a[array_lower(a, 1)][array_lower(a, 2)][array_lower(a, 3)] when 4 then a[array_lower(a, 1)][array_lower(a, 2)][array_lower(a, 3)][array_lower(a, 4)] when 5 then a[array_lower(a, 1)][array_lower(a, 2)][array_lower(a, 3)][array_lower(a, 4)][array_lower(a, 5)] when 6 then a[array_lower(a, 1)][array_lower(a, 2)][array_lower(a, 3)][array_lower(a, 4)][array_lower(a, 5)][array_lower(a, 6)] end;
alter table t alter column b type integer using (case array_ndims(b) when 1 then b[array_lower(b, 1)] when 2 then b[array_lower(b, 1)][array_lower(b, 2)] when 3 then b[array_lower(b, 1)][array_lower(b, 2)][array_lower(b, 3)] when 4 then b[array_lower(b, 1)][array_lower(b, 2)][array_lower(b, 3)][array_lower(b, 4)] when 5 then b[array_lower(b, 1)][array_lower(b, 2)][array_lower(b, 3)][array_lower(b, 4)][array_lower(b, 5)] when 6 then b[array_lower(b, 1)][array_lower(b, 2)][array_lower(b, 3)][array_lower(b, 4)][array_lower(b, 5)][array_lower(b, 6)] end)::integer;
